void Solver::rephase() {
    // 1. Reset the rephase counter – we have just performed a re‑phase.
    rephases = 0;

    // 2. Make the next re‑phase happen sooner:
    //    shrink the trail‑size threshold a bit more aggressively than the original 0.9 factor.
    threshold = static_cast<int>(threshold * 0.85);

    // 3. Allow a few more re‑phases before the next trigger.
    //    Grow the limit slowly (20 % increase) and add a small constant to avoid stagnation.
    rephase_limit = static_cast<int>(rephase_limit * 1.2) + 1024;

    // 4. Refresh the saved phase information.
    //    - 60 % of the time keep the best local phase,
    //    - 20 % of the time invert it,
    //    - 20 % of the time pick a random polarity.
    int r = rand() % 100;
    if (r < 60) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 80) {
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // 5. Reset the VSIDS increment to avoid floating‑point overflow and give a fresh start.
    var_inc = 1.0;
}
